import itertools
# Gaussian integers, exact
def mul(z,w): return (z[0]*w[0]-z[1]*w[1], z[0]*w[1]+z[1]*w[0])
def conj(z):  return (z[0],-z[1])
one=(1,0)
def gate(a,b,c,d,x,y): return x==(a+b)%2 and y==(b+c)%2 and d==(a+b+c)%2
def Fs(f,a,b,c,d,x,y):
    if gate(a,b,c,d,x,y): return f if (a==1 and b==1 and c==1) else one
    return (0,0)

def holds(f, S):           # S = subset of {0,1,2,3,4} = L1,L2,L3,R1,R2
    for a,b,c,d in itertools.product((0,1),repeat=4):
        x=(a+b)%2; y=(x+c)%2; t=(y+d)%2; w=(c+d)%2; v=(b+w)%2; u=(b+c)%2
        F=[Fs(f,a,b,c,y,x,u),Fs(f,a,u,d,t,y,v),Fs(f,b,c,d,v,u,w),
           Fs(f,x,c,d,t,y,w),Fs(f,a,b,w,t,x,v)]
        F=[conj(z) if i in S else z for i,z in enumerate(F)]
        if mul(mul(F[0],F[1]),F[2]) != mul(F[3],F[4]): return False
    return True

# solution set over a search box
box=[(re,im) for re in range(-3,4) for im in range(-3,4)]
base={f for f in box if holds(f,frozenset())}
print("original solution set:", sorted(base))
print()
same=wider=narrower=other=0
tally={}
for r in range(1,6):
    for S in itertools.combinations(range(5),r):
        s={f for f in box if holds(f,frozenset(S))}
        if s==base: v="Same"
        elif base<s:  v="WIDER"; 
        elif s<base:  v="Narrower"
        else: v="Incomparable"
        tally.setdefault(v,[]).append((S,sorted(s-base)))
for v in ("Same","WIDER","Narrower","Incomparable"):
    if v in tally: print(f"{v:14} {len(tally[v]):3}")
print()
print("the extra solutions each WIDER variant admits:")
seen=set()
for S,extra in tally.get("WIDER",[]):
    if tuple(extra) not in seen:
        seen.add(tuple(extra)); print("   ", extra)
print()
print("which factors carry f at (a,b,c,d)=(1,1,1,1):")
a=b=c=d=1
x=(a+b)%2; y=(x+c)%2; t=(y+d)%2; w=(c+d)%2; v=(b+w)%2; u=(b+c)%2
names=["L1","L2","L3","R1","R2"]
args=[(a,b,c,y,x,u),(a,u,d,t,y,v),(b,c,d,v,u,w),(x,c,d,t,y,w),(a,b,w,t,x,v)]
for n,g in zip(names,args):
    print(f"   {n}: {'f' if (g[0]==1 and g[1]==1 and g[2]==1) else '1'}")
